@dataclass(frozen=True)
class Stage298GuardDecision:
    scenario_id: str
    allowed: bool
    decision_code: str
    action: str
    confidence: float
    remediation: str
    pr_refs: List[str]


def default_attack_and_remediated_payloads() -> Dict[str, Dict[str, Dict[str, Any]]]:
    return {
        sid: {
            "attack": dict(pair["attack"]),
            "remediated": dict(pair["remediated"]),
        }
        for sid, pair in _DEFAULT_PAYLOADS.items()
    }


def evaluate_stage298_scenario(scenario_id: str, payload: Dict[str, Any]) -> Stage298GuardDecision:
    """Evaluate one of the 16 Stage 298 deterministic security/protocol scenarios (512 PRs / 80 repos)."""
    spec = next((s for s in STAGE298_SCENARIOS if s["id"] == scenario_id), None)
    if spec is None:
        raise ValueError(f"Unknown Stage 298 scenario_id: {scenario_id}")
    pr_refs = list(STAGE298_PR_GROUPS[scenario_id])
    violation_code = spec["violation_code"]
    expected = _DEFAULT_PAYLOADS[scenario_id]["remediated"]

    ok = all(payload.get(k) == v for k, v in expected.items())
    if ok:
        return Stage298GuardDecision(
            scenario_id=scenario_id,
            allowed=True,
            decision_code=f"STAGE298_{scenario_id.replace('-', '_')}_REMEDIATED_PASS",
            action="Act automatically",
            confidence=0.99,
            remediation="All Stage 298 deterministic protocol & security invariants satisfied.",
            pr_refs=pr_refs,
        )
    return Stage298GuardDecision(
        scenario_id=scenario_id,
        allowed=False,
        decision_code=violation_code,
        action="Send to a human",
        confidence=0.98,
        remediation=f"Enforce {spec['guard_fn']} across {spec['citations']}.",
        pr_refs=pr_refs,
    )
